module manyTests {
  var x: int
  action init = x' = 0

  run firstTest = init.then(x' = 1).then(all { assert(x == 1), x' = x })
  run secondTest = init.then(x' = 2).then(all { assert(x == 2), x' = x })
}

// Regression test for https://github.com/informalsystems/quint/issues/1281
// ITF export did not have support for sum types
module sum {
    type T = None | Some(int)
    var x: T
    action init = x' = None
    action step = x' = match x { None => Some(1) | Some(n) => Some(n+1) }
    run xTest = init.then(step).then(step).then(step)
}

// See:
// https://github.com/informalsystems/quint/issues/1133
module lastActionInRun {
    var s: str

    action A = 
        s' = "A"

    action B = 
        s' = "B"

    run t1 = A.then(A).then(B)

    run t2 = A.then(A).then(B).then(s'=s)
}
